                  type="text" 
                  id="grand-lib-search-input" 
                  placeholder="Search 12 volumes by syndrome, biomarker, pulse, herb, or clinical protocol (e.g. Nabz, hs-CRP, FibroScan, Suranjan, PCOS)..." 
                  oninput="handleGrandLibrarySearch(this.value)"
